"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7152],{93071:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"WeaponServer","desc":"Authoritative weapon server. Infers the weapon from the requester\'s equipped\\nTool and never trusts client-claimed hits.\\n\\nPlan 2 adds authoritative hitscan fire (`ReqFireWeapon`), authoritative\\nreload (`ReqReloadWeapon`), and ammo initialisation on gun equip\\n(`WeaponMagSync` pushed to the owning client immediately; the shared\\nammo pool is owned by `AmmoManager` and synced via `AmmoPoolSync`).\\n\\nPlan 3 adds server-side rocket (projectile) cast via FastCast2. Throwable\\nweapons (grenade fuse + C4 manual) are handled via `ReqThrowProjectile` and\\n`ReqDetonate`.\\n\\nHitscan is lag-compensated: `ReqFireWeapon` carries the client\'s Chrono\\nrender time and NPC hit tests run through\\n`LagCompensation` (rewound to that time, clamped server-side).","realm":["Server"],"source":{"line":22,"path":"src/ServerScriptService/WeaponServer.server.luau"}}')}}]);